#!/usr/bin/env python3
import argparse,json,hashlib,collections
def main():
 ap=argparse.ArgumentParser();ap.add_argument('--lanes',required=True);ap.add_argument('--recipes',required=True);ap.add_argument('--exclusions',required=True);ap.add_argument('--output',required=True);a=ap.parse_args();l=json.load(open(a.lanes));r=json.load(open(a.recipes));e=json.load(open(a.exclusions)); want={x['cpv'] for x in l['packages'] if x['lane'].startswith('pgo-')}; ready={x['cpv'] for x in r['packages'] if x['state']=='recipe-ready'}; exc={x['cpv'] for x in e['records']}; overlap=ready&exc; missing=want-(ready|exc); extra=(ready|exc)-want
 out={'record_type':'workload-coverage-audit','schema_version':1,'pgo_package_count':len(want),'recipe_ready_count':len(ready),'exclusion_count':len(exc),'overlap':sorted(overlap),'missing':sorted(missing),'extra':sorted(extra),'coverage_pass':not overlap and not missing and not extra,'source_lanes':l['sha256'],'source_recipes':r['sha256'],'source_exclusions':e['sha256']};out['sha256']=hashlib.sha256(json.dumps(out,sort_keys=True,separators=(',',':')).encode()).hexdigest();json.dump(out,open(a.output,'w'),sort_keys=True,indent=2);open(a.output,'a').write('\n');print(out['coverage_pass'],len(want),len(ready),len(exc),len(overlap),len(missing))
if __name__=='__main__':main()
